// CANDADO#1 · el "camino al supervisor": el re-gate LEE la salida de ESTE nodo.
// PODA 2026-07-21 (CC#3 · fix finding overflow exec 61405): el re-gate task embebe
// JSON.stringify(este output) y el límite del endpoint de agentes es 8000 chars.
// Antes threadeábamos deep_scan_data crudo (biography + profile_pic_url + external_url
// + el response de re-discovery) → ~8.4k chars → E-INPUT-INVALID → default observar.
// Ahora enviamos un SOBRE COMPACTO: por competidor nombre · tipo · source · trust_level
// · positioning corto · evidencia dura clave (followers/following/posts/verified/platform).
// Solo apify_scrape genuino enriquece; el resto → auto_discovery honesto.
const unwrap = $('[ANCHOR] Guard geo+canonical').first().json;
let verify = {};
try { verify = $('[APIFY] Scrape-Verify').first().json || {}; } catch (e) { verify = {}; }
const vlist = Array.isArray(verify.competitors) ? verify.competitors : [];
const byName = {};
for (const c of vlist) { byName[String((c && c.name) || '').trim().toLowerCase()] = c; }
const comps = Array.isArray(unwrap.competitors) ? unwrap.competitors : [];
function compactEvidence(d) {
  const out = {};
  if (!d || typeof d !== 'object') return out;
  ['followers_count', 'following_count', 'posts_count', 'is_verified', 'platform'].forEach(function (k) {
    if (d[k] !== undefined) out[k] = d[k];
  });
  return out;
}
const enriched = comps.map(function (c) {
  const name = String((c && c.name) || '').trim();
  const v = byName[name.toLowerCase()];
  const row = { name: name, competitor_type: (c && c.competitor_type) || 'direct' };
  if (v && v.source === 'apify_scrape') {
    row.source = 'apify_scrape';
    row.trust_level = v.trust_level || 'untrusted';
    row.scraped = true;
    if (typeof v.positioning === 'string' && v.positioning) row.positioning = v.positioning.slice(0, 150);
    row.evidence = compactEvidence(v.deep_scan_data);
  } else {
    row.source = 'auto_discovery';
    row.trust_level = 'untrusted';
    row.scraped = false;
  }
  return row;
});
const scraped = enriched.filter(function (c) { return c.source === 'apify_scrape'; }).length;
return [{ json: { client_id: unwrap.client_id || null, competitors: enriched, _scrape_verify: { scraped_count: scraped, total: enriched.length } } }];

// [ANCHOR] Guard geo+canonical · CC#3 2026-07-21 · fix drift de región del re-discovery.
// Semilla = competitor_list canónico (clients.config.apify · ancla de región · SIEMPRE presente).
// Los descubiertos se AGREGAN solo si corroboran el canónico (dup) o comparten token de mercado
// con el cliente; los de otra región -> DROP. Jamás cambia región · puede extender.
// Fail-open: sin canónico (loader falló) -> pasa la lista descubierta sin tocar (no romper corrida).
const reDisc = $("Re-discovery INLINE (onboarding-specialist)").first().json || {};
let loaded = {};
try { loaded = $("[ANCHOR] Load client (canonical competitor_list)").first().json || {}; } catch (e) { loaded = {}; }
const cfg = (loaded.config || (loaded.client && loaded.client.config) || {});
const canonical = (((cfg.apify || {}).competitor_list) || []);
const clientName = ($('Validate Deal Data').item.json.client_name) || loaded.name || '';
const clientWebsite = ($('Validate Deal Data').item.json.website) || loaded.website_url || '';
const discovered = Array.isArray(reDisc.competitors) ? reDisc.competitors : [];
if (!Array.isArray(canonical) || canonical.length === 0) {
  return [{ json: Object.assign({}, reDisc, { _anchor: { applied: false, reason: 'no_canonical' } }) }];
}
const STOP = new Set(['surf','surfing','camp','camps','school','lodge','house','guesthouse','retreat','retreats','yoga','kite','spa','resort','hostel','hotel','escape','center','centre','club','the','and','nourish','wellness','boutique','academy','experience','village','coliving','coworking','www','com','http','https','pt','co','net','org','home']);
const norm = function (s) { return String(s || '').toLowerCase(); };
const tokens = function (s) { return norm(s).replace(/https?:\/\//g,' ').replace(/[^a-z0-9]+/g,' ').split(' ').filter(function(t){ return t.length>=4 && !STOP.has(t); }); };
const domainTokens = function (url) { const m = norm(url).match(/\/\/([^/]+)/) || norm(url).match(/^([^/]+)/); const host = m ? m[1] : norm(url); return host.replace(/[^a-z0-9]+/g,' ').split(' ').filter(function(t){ return t.length>=4 && !STOP.has(t); }); };
const canonKey = function (c) { return norm(c.name).replace(/[^a-z0-9]/g,''); };
const market = new Set();
tokens(clientName).forEach(function(t){ market.add(t); });
domainTokens(clientWebsite).forEach(function(t){ market.add(t); });
canonical.forEach(function(c){ tokens(c.name).forEach(function(t){ market.add(t); }); domainTokens(c.website).forEach(function(t){ market.add(t); }); });
const marketArr = Array.from(market);
const canonSet = new Set(canonical.map(canonKey));
const out = []; const seen = new Set();
canonical.forEach(function(c){ const k = canonKey(c); if (seen.has(k)) return; seen.add(k); out.push({ name: c.name, handles: c.handles || (c.instagram ? { instagram: c.instagram } : undefined), website: c.website || undefined, competitor_type: c.competitor_type || 'direct', _anchor_src: 'canonical' }); });
const dropped = [];
discovered.forEach(function(c){ const k = norm(c && c.name).replace(/[^a-z0-9]/g,''); if (!k) return; if (seen.has(k) || canonSet.has(k)) return; const hay = norm(c.name) + ' ' + norm(c.website || ''); const inMarket = marketArr.some(function(t){ return hay.indexOf(t) >= 0; }); if (inMarket) { seen.add(k); out.push(Object.assign({}, c, { _anchor_src: 'discovered_in_market' })); } else { dropped.push(c.name); } });
return [{ json: Object.assign({}, reDisc, { competitors: out, _anchor: { applied: true, canonical_count: canonical.length, kept: out.length, dropped: dropped } }) }];
